return $input.all().map(function (it) {
  const j = it.json;
  const fromText = (j.from && j.from.text) || '';
  const fromAddr = (j.from && j.from.value && j.from.value[0] && j.from.value[0].address) || '';
  let body = (j.text && String(j.text).trim()) || '';
  if (!body) body = String(j.textAsHtml || j.html || '').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ');
  body = body.replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim().slice(0, 6000);
  return { json: { gmailId: j.id, threadId: j.threadId, subject: j.subject || '(no subject)', fromText: fromText, fromAddress: fromAddr, receivedAt: j.date || '', body: body } };
});

const emails = $('Prepare Email').all();
const now = DateTime.now();
return $input.all().map(function (it, i) {
  const o = it.json.output || {};
  const e = (emails[i] && emails[i].json) || {};
  const sessions = [];
  (Array.isArray(o.sessions) ? o.sessions : []).slice(0, 10).forEach(function (s) {
    const st = DateTime.fromISO(String((s && s.start) || ''), { setZone: true });
    if (!st.isValid) return;
    let en = DateTime.fromISO(String((s && s.end) || ''), { setZone: true });
    if (!en.isValid || en <= st) en = st.plus({ minutes: 60 });
    if (en < now) return;
    sessions.push({ startISO: st.toISO(), endISO: en.toISO() });
  });
  return { json: {
    gmailId: e.gmailId, threadId: e.threadId, subject: e.subject, fromText: e.fromText, fromAddress: e.fromAddress,
    isEvent: o.isEvent === true && sessions.length > 0, eventType: o.eventType || 'event',
    title: String(o.title || e.subject || 'Event').slice(0, 200), sessions: sessions,
    link: o.link || '', organizer: o.organizer || e.fromText || '', location: o.location || '',
    summary: String(o.summary || '').slice(0, 500), notes: String(o.notes || '').slice(0, 300),
    recordStatus: it.json.error ? 'llm_error' : (o.isEvent === true ? 'past_or_undated' : 'not_event')
  }, pairedItem: { item: i } };
});

function selfDeclined(e) { return (e.attendees || []).some(function (a) { return a.self && a.responseStatus === 'declined'; }); }
function busyInterval(e) {
  if (!e || !e.start || e.status === 'cancelled' || selfDeclined(e)) return null;
  if (e.eventType === 'workingLocation' || e.eventType === 'birthday') return null;
  if (e.start.dateTime) {
    if (e.transparency === 'transparent') return null;
    return { s: DateTime.fromISO(e.start.dateTime), e: DateTime.fromISO(e.end.dateTime), allDay: false };
  }
  if (e.start.date) return { s: DateTime.fromISO(e.start.date, { zone: 'Europe/Rome' }).startOf('day'), e: DateTime.fromISO(e.end.date, { zone: 'Europe/Rome' }).startOf('day'), allDay: true };
  return null;
}

function readBusy(node) {
  const res = { events: [], ok: true, failed: [], checked: [] };
  let items = [];
  try { items = $(node).all(); } catch (e) { res.ok = false; res.failed.push('busy calendars not read'); return res; }
  if (!items.length) { res.ok = false; res.failed.push('busy calendars returned nothing'); }
  items.forEach(function (it) {
    const e = it.json || {};
    if (e.__summary) { res.checked = e.calendars || []; return; }
    if (e.__calendarError) { res.ok = false; res.failed.push(e.calendarName || e.calendarId); return; }
    if (e.error) { res.ok = false; res.failed.push(String((e.error && e.error.message) || e.error)); return; }
    if (e.start) res.events.push(e);
  });
  return res;
}

const events = $('Is Schedulable?').all(0);
const res = readBusy('Get Busy Events');
const calendarOk = res.ok;
const cal = [];
res.events.forEach(function (e) {
  const b = busyInterval(e);
  if (!b) return;
  // A public holiday does not make you unavailable for a webinar; it only matters for meetings.
  if (b.allDay && String(e.__calendarId || '').indexOf('#holiday@') >= 0) return;
  cal.push({ b: b, ev: e, calendar: e.__calendarName || e.__calendarId || '' });
});
return events.map(function (it, i) {
  const ev = it.json;
  const conflicts = [];
  const seen = {};
  let alreadyInCalendar = false;
  ev.sessions.forEach(function (s) {
    const ss = DateTime.fromISO(s.startISO), se = DateTime.fromISO(s.endISO);
    cal.forEach(function (c) {
      if (!(ss < c.b.e && se > c.b.s)) return;
      const sameSlot = !c.b.allDay && Math.abs(c.b.s.diff(ss, 'minutes').minutes) <= 5 && Math.abs(c.b.e.diff(se, 'minutes').minutes) <= 5;
      if (sameSlot && ev.sessions.length === 1) { alreadyInCalendar = true; return; }
      if (seen[c.ev.id]) return;
      seen[c.ev.id] = true;
      conflicts.push({
        id: c.ev.id, calendar: c.calendar, summary: c.ev.summary || '(busy)', allDay: c.b.allDay,
        startISO: c.b.s.toISO(), endISO: c.b.e.toISO(),
        organizerSelf: !!(c.ev.organizer && c.ev.organizer.self), organizerEmail: (c.ev.organizer && c.ev.organizer.email) || '',
        attendees: (c.ev.attendees || []).map(function (a) { return { email: a.email, self: !!a.self, resource: !!a.resource }; })
      });
    });
  });
  return { json: Object.assign({}, ev, {
    conflicts: conflicts, calendarOk: calendarOk, alreadyInCalendar: alreadyInCalendar,
    recordStatus: alreadyInCalendar ? 'already_in_calendar' : ev.recordStatus
  }), pairedItem: { item: i } };
});

const ZONE = 'Europe/Rome';
const URL = 'https://YOUR-N8N-HOST/webhook/mailroom-decide-CHANGE-ME';
function fmtRange(a, b) { const s = DateTime.fromISO(a).setZone(ZONE); const e = DateTime.fromISO(b).setZone(ZONE); return s.toFormat('ccc d LLL yyyy, HH:mm') + '-' + (s.hasSame(e, 'day') ? e.toFormat('HH:mm') : e.toFormat('ccc d LLL HH:mm')); }
const TYPE = { webinar: 'Webinar', course: 'Course', conference: 'Conference', workshop: 'Workshop', seminar: 'Seminar', meetup: 'Meetup', event: 'Event' };
return $input.all().map(function (it, i) {
  const ev = it.json;
  const token = String(ev.token || ev.data || '');
  const link = function (a) { return URL + '?t=' + encodeURIComponent(token) + '&a=' + a; };
  const kind = TYPE[ev.eventType] || 'Event';
  const first = DateTime.fromISO(ev.sessions[0].startISO).setZone(ZONE);
  const state = !ev.calendarOk ? 'CHECK' : (ev.conflicts.length ? 'CONFLICT' : 'FREE');
  const L = [];
  L.push(kind + ': ' + ev.title);
  ev.sessions.forEach(function (s, k) { L.push((ev.sessions.length > 1 ? 'Session ' + (k + 1) + ': ' : 'When: ') + fmtRange(s.startISO, s.endISO) + ' (Europe/Rome)'); });
  if (ev.location || ev.link) L.push('Where: ' + [ev.location, ev.link].filter(Boolean).join(' - '));
  if (ev.organizer) L.push('From: ' + ev.organizer);
  if (ev.summary) L.push('', ev.summary);
  if (ev.notes) L.push('Note: ' + ev.notes);
  if (ev.threadId) L.push('Original email: https://mail.google.com/mail/u/0/#all/' + ev.threadId);
  L.push('');
  if (state === 'FREE') {
    L.push('YOUR CALENDAR: FREE at ' + (ev.sessions.length > 1 ? 'every session.' : 'this time.'), '');
    L.push('Add to my calendar:', link('add'), '', 'Ignore it:', link('ignore'));
  } else if (state === 'CONFLICT') {
    L.push('YOUR CALENDAR: CONFLICT with');
    ev.conflicts.forEach(function (c) {
      const who = (c.attendees || []).filter(function (a) { return !a.self && !a.resource && a.email; }).map(function (a) { return a.email; });
      L.push('  - ' + c.summary + ' - ' + (c.allDay ? 'all day ' + DateTime.fromISO(c.startISO).setZone(ZONE).toFormat('ccc d LLL') : fmtRange(c.startISO, c.endISO)) + (who.length ? ' (with ' + who.slice(0, 4).join(', ') + (who.length > 4 ? ', ...' : '') + ')' : ''));
    });
    L.push('', 'KEEP my existing schedule (do not add this ' + kind.toLowerCase() + '):', link('keep'), '');
    L.push('SWAP to the new ' + kind.toLowerCase() + ' (add it, and draft reschedule requests for the meetings above):', link('swap'));
  } else {
    L.push('YOUR CALENDAR: could not be checked right now.', '');
    L.push('Add to my calendar anyway:', link('add'), '', 'Ignore it:', link('ignore'));
  }
  L.push('', '--', 'Each link opens a confirmation page. Nothing changes until you press Confirm. This note has no recipient and cannot be sent by accident.');
  const subject = '[Inbox Pilot] ' + state + ' - ' + kind + ': ' + ev.title.slice(0, 80) + ' - ' + first.toFormat('ccc d LLL HH:mm');
  return { json: Object.assign({}, ev, { token: token, draftSubject: subject, draftBody: L.join('\n'),
    sessionsJson: JSON.stringify(ev.sessions), conflictsJson: JSON.stringify(ev.conflicts) }), pairedItem: { item: i } };
});
